function makeBuilding(x,z,w,d,h,color,seed,shop=false){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);let wall=mat(color),trim=mat(0xf5e9d2),dark=mat(0x49666a),roof=roofM[seed%roofM.length];box(g,0,h/2,0,w,h,d,wall);box(g,0,h+.16,0,w+.34,.3,d+.34,roof);
// gable on the shorter front side
const roofGeom=new THREE.ConeGeometry(Math.max(w,d)*.78,.95,4);const peak=new THREE.Mesh(roofGeom,roof);peak.rotation.y=Math.PI/4;peak.scale.set(1,.8,Math.min(w,d)/Math.max(w,d));peak.position.set(0,h+.42,d/2-.08);peak.castShadow=true;g.add(peak);
// windows on front facade
const n=Math.max(1,Math.floor(w/2.5));for(let i=0;i<n;i++){let wx=(i-(n-1)/2)*(w/(n+.2));for(let floor=0;floor<Math.max(1,Math.floor((h-1.6)/2.4));floor++){let wy=1.65+floor*2.35;box(g,wx,wy,d/2+.035,.72,.95,.1,dark);box(g,wx,wy,d/2+.1,.08,1.02,.08,trim);box(g,wx,wy,d/2+.1,.72,.07,.08,trim);box(g,wx,wy,d/2+.15,.055,.86,.04,trim);}}
box(g,0,.75,d/2+.08,.82,1.5,.13,trim);box(g,0,.74,d/2+.16,.5,1.1,.08,mat(0x8b7563));if(shop){box(g,0,2.45,d/2+.12,w*.7,.48,.12,mat(0xf4ddae));box(g,0,2.47,d/2+.2,w*.56,.23,.04,mat(0x547b78));}
// chimney and small planter
if(seed%2===0){box(g,w*.27,h+.85,-d*.2,.48,1.5,.5,mat(0xb76f58));}
box(g,-w*.22,.28,d/2+.65,.7,.42,.55,mat(seed%2?0x879879:0xb97f66));const shrubs=mat(0x6e9471);for(let a=0;a<3;a++){let leaf=new THREE.Mesh(new THREE.SphereGeometry(.24,8,6),shrubs);leaf.position.set(-w*.22+(a-1)*.2,.65,d/2+.65);leaf.castShadow=true;g.add(leaf)}
return g;}

