const buildingWalls=[],interactables=[];
function makeBuilding(x,z,w,d,h,color,seed,shop=false,accessible=true){
 const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
 const wall=mat(color),inside=mat(new THREE.Color(color).multiplyScalar(.72)),trim=mat(0xf5e9d2),dark=mat(0x49666a),roof=roofM[seed%roofM.length],doorWidth=1.12,doorHeight=2.28,thickness=.24;
 if(accessible){
  box(g,0,.09,0,w-.32,.18,d-.32,mat(seed%2?0xb89c78:0xc2aa83));
  box(g,0,h-.13,0,w-.3,.18,d-.3,inside);
  const frontSegments=[[-w/2+thickness/2,(-doorWidth/2-w/2)/2,w/2-doorWidth/2],[doorWidth/2+w/2, (doorWidth/2+w/2)/2,w/2-doorWidth/2]];
  for(const [unused,cx,sw] of frontSegments){if(sw>.1){box(g,cx,h/2,d/2-thickness/2,sw,h,thickness,wall);buildingWalls.push({x:x+cx,z:z+d/2-thickness/2,w:sw,d:thickness})}}
  box(g,0,h/2,-d/2+thickness/2,w,h,thickness,wall);buildingWalls.push({x,z:z-d/2+thickness/2,w,d:thickness});
  for(const side of [-1,1]){box(g,side*(w/2-thickness/2),h/2,0,thickness,h,d,wall);buildingWalls.push({x:x+side*(w/2-thickness/2),z,w:thickness,d})}
 }else box(g,0,h/2,0,w,h,d,wall);
 box(g,0,h+.16,0,w+.34,.3,d+.34,roof);
 // gable on the shorter front side
 const roofGeom=new THREE.ConeGeometry(Math.max(w,d)*.78,.95,4);const peak=new THREE.Mesh(roofGeom,roof);peak.rotation.y=Math.PI/4;peak.scale.set(1,.8,Math.min(w,d)/Math.max(w,d));peak.position.set(0,h+.42,d/2-.08);peak.castShadow=true;g.add(peak);
 if(accessible){
  const pivot=new THREE.Group();pivot.position.set(-doorWidth/2,0,d/2+.035);g.add(pivot);const door=box(pivot,doorWidth/2,doorHeight/2,0,doorWidth,doorHeight,.12,mat(seed%2?0x876b50:0x9a7051));box(pivot,doorWidth*.77,1.12,.068,.045,.045,.025,trim);box(pivot,doorWidth*.2,1.12,.075,.09,.09,.04,mat(0xc69b55));
  const doorItem={kind:'door',label:'Door',x,z:z+d/2+.25,mesh:pivot,open:false,doorWidth,doorHeight};interactables.push(doorItem);
  const n=Math.max(1,Math.floor(w/2.7));for(let i=0;i<n;i++){let wx=(i-(n-1)/2)*(w/(n+.2));for(let floor=0;floor<Math.min(2,Math.max(1,Math.floor((h-1.6)/2.5)));floor++){
   const wy=1.58+floor*2.45,ww=.82,wh=1.05,front=d/2+.035;box(g,wx,wy,front,ww,wh,.08,dark);box(g,wx,wy,front+.055,.07,wh+.12,.08,trim);box(g,wx,wy,front+.06,ww+.12,.07,.08,trim);box(g,wx,wy,front+.08,.045,wh,.035,trim);box(g,wx,wy,front+.08,ww,.045,.035,trim);
   const shutterColor=mat(seed%2?0x68877f:0x8f6557),leaves=[];for(const side of [-1,1]){const hinge=new THREE.Group();hinge.position.set(wx+side*ww/2,wy,front+.09);g.add(hinge);box(hinge,-side*ww/4,0,0,ww/2,wh,.08,shutterColor);box(hinge,-side*ww/4,0,.045,.035,wh-.12,.025,trim);leaves.push({hinge,side})}
   interactables.push({kind:'window',label:'Window',x:x+wx,z:z+front+.45,leaves,open:false});
  }}
  if(shop){box(g,0,2.45,d/2+.12,w*.7,.48,.12,mat(0xf4ddae));box(g,0,2.47,d/2+.2,w*.56,.23,.04,mat(0x547b78));}
  // Simple, low interior furnishings make each room read as a lived-in space.
  const furniture=mat(seed%2?0xb17f59:0x879879);box(g,-w*.23,.48,-d*.12,1.15,.82,.72,furniture);box(g,w*.24,.34,-d*.23,.9,.52,.62,mat(0xd0b98e));
 }
 // chimney and small planter
 if(seed%2===0){box(g,w*.27,h+.85,-d*.2,.48,1.5,.5,mat(0xb76f58));}
 box(g,-w*.22,.28,d/2+.65,.7,.42,.55,mat(seed%2?0x879879:0xb97f66));const shrubs=mat(0x6e9471);for(let a=0;a<3;a++){let leaf=new THREE.Mesh(new THREE.SphereGeometry(.24,8,6),shrubs);leaf.position.set(-w*.22+(a-1)*.2,.65,d/2+.65);leaf.castShadow=true;g.add(leaf)}
 return g;
}

