 const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
 let id=0;const pending=new Map();const exceptions=[];
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')exceptions.push(m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
 function cmd(method,params={}){return new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))})}
 async function ev(expression){const r=await cmd('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.result.exceptionDetails)throw Error(r.result.exceptionDetails.text);return r.result.result.value}
 await cmd('Page.enable');await cmd('Runtime.enable');
 for(let i=0;i<100;i++){try{if(await ev('!!window.__test'))break}catch{}await sleep(200)}
 const test=await ev(`(()=>{const t=window.__test;if(!t)throw Error('test hooks missing');const door=t.interactables.find(x=>x.kind==='door');t.player.position.set(door.x,0,door.z-1.6);t.updateInteractionPrompt();const doorPrompt=document.querySelector('#interact').textContent;const closedBlocks=t.collides(door.x,door.z);t.toggleInteractable();const openState=door.open,openAllows=!t.collides(door.x,door.z),openPrompt=document.querySelector('#interact').textContent;t.toggleInteractable();const closeBlocks=t.collides(door.x,door.z);const win=t.interactables.find(x=>x.kind==='window');t.player.position.set(win.x,0,win.z);t.updateInteractionPrompt();const windowPrompt=document.querySelector('#interact').textContent;document.querySelector('#interact').click();const buttonOpened=win.open;document.querySelector('#interact').click();const buttonClosed=!win.open;const allClosed=win.leaves.every(x=>Math.abs(x.hinge.rotation.y)<1e-8);t.player.position.set(win.x,0,win.z);t.updateInteractionPrompt();return {doorPrompt,closedBlocks,openState,openAllows,openPrompt,closeBlocks,windowPrompt,buttonOpened,buttonClosed,allClosed,visible:document.querySelector('#interact').classList.contains('visible')}})()`);
 if(!test.closedBlocks||!test.openState||!test.openAllows||!test.closeBlocks||!test.buttonOpened||!test.buttonClosed||!test.allClosed||!test.visible)throw Error(`Interaction assertions failed: ${JSON.stringify(test)}`);
 await ev("document.querySelector('#start').click(); true");
 const png=await cmd('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
 if(png.result&&png.result.data)fs.writeFileSync('/tmp/opencode/little-harbor-playing.png',Buffer.from(png.result.data,'base64'));
 console.log(JSON.stringify({result:'PASS',test,exceptions,screenshot:'/tmp/opencode/little-harbor-playing.png'},null,2));
 ws.close();chrome.kill('SIGTERM');
})().catch(e=>{console.error(e);chrome.kill('SIGTERM');process.exitCode=1});
